#include <iostream>
#include <vector>
using namespace std;

// Đệ quy có nhớ (memoization): Fibonacci O(n) thay vì O(2^n)
long long fib(int n, vector<long long>& nho) {
    if (n <= 1) return n;
    if (nho[n] != -1) return nho[n];
    return nho[n] = fib(n - 1, nho) + fib(n - 2, nho);
}

// Quay lui: sinh mọi tập con (Subsets)
void sinhTapCon(const vector<int>& a, int batDau, vector<int>& dangChon, vector<vector<int>>& kq) {
    kq.push_back(dangChon);
    for (int i = batDau; i < (int)a.size(); i++) {
        dangChon.push_back(a[i]);            // Chọn
        sinhTapCon(a, i + 1, dangChon, kq);  // Thử tiếp
        dangChon.pop_back();                 // Bỏ chọn (quay lui)
    }
}

// Quay lui: sinh mọi hoán vị (Permutations) bằng cách đổi chỗ
void sinhHoanVi(vector<int>& a, int k, vector<vector<int>>& kq) {
    if (k == (int)a.size()) {
        kq.push_back(a);
        return;
    }
    for (int i = k; i < (int)a.size(); i++) {
        swap(a[k], a[i]);
        sinhHoanVi(a, k + 1, kq);
        swap(a[k], a[i]); // trả lại như cũ
    }
}


